-- Calibre Procedures v2: deepen the mechanical-service procedure.
-- Simple physical actions remain simple. Inspection, decision, timing and QC
-- checks become structured, and useful abnormal outcomes reveal follow-ups.

with config(step_key, check_key, answer_kind, answer_options, problem_values, tool_key, knowledge_scope) as (
  values
  ('pre_service_timing','timing_specs','choice','[{"value":"documented","label":"Documented reference confirmed"},{"value":"manual_verified","label":"Manually verified"},{"value":"unknown","label":"Still unknown"}]'::jsonb,'[]'::jsonb,'knowledge','timing_specs'),
  ('pre_service_timing','baseline_run','tool_result','[]'::jsonb,'[]'::jsonb,'timing','pre_service'),
  ('pre_service_timing','baseline_observation','choice','[{"value":"stable","label":"Stable enough to use"},{"value":"unstable","label":"Unstable trace / rate"},{"value":"beat_error","label":"Beat error concern"},{"value":"position_variation","label":"Large positional variation"},{"value":"other","label":"Other abnormal behaviour"}]'::jsonb,'["unstable","beat_error","position_variation","other"]'::jsonb,'diagnosis','timing'),
  ('demagnetise_check','recheck_magnetism','choice','[{"value":"clear","label":"Clear after check"},{"value":"still_detected","label":"Still detected"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'["still_detected","uncertain"]'::jsonb,'diagnosis','magnetism'),
  ('demagnetise_check','timing_effect','tool_result','[]'::jsonb,'[]'::jsonb,'timing','pre_service'),
  ('movement_removal','stem_crown_removal','choice','[{"value":"smooth_release","label":"Released smoothly"},{"value":"resistance","label":"Resistance / drag"},{"value":"unable","label":"Unable to release safely"},{"value":"uncertain","label":"Release method uncertain"}]'::jsonb,'["resistance","unable","uncertain"]'::jsonb,'diagnosis','keyless'),
  ('movement_removal','case_retention','choice','[{"value":"normal","label":"Normal and serviceable"},{"value":"unusual","label":"Unusual arrangement"},{"value":"damaged_missing","label":"Damaged or missing retention part"},{"value":"distorting","label":"Retention appears to distort movement"}]'::jsonb,'["damaged_missing","distorting"]'::jsonb,'diagnosis','casing'),
  ('movement_removal','case_movement_marks','choice','[{"value":"identity_confirmed","label":"Identity confirmed"},{"value":"new_marks","label":"New identifying marks found"},{"value":"still_uncertain","label":"Identity still uncertain"}]'::jsonb,'["still_uncertain"]'::jsonb,'research','identification'),
  ('strip_down','dial_hands','choice','[{"value":"normal","label":"Removed normally"},{"value":"tight","label":"Unusually tight / resistant"},{"value":"damage_found","label":"Damage found"},{"value":"unusual_fitting","label":"Unusual fitting / construction"}]'::jsonb,'["tight","damage_found","unusual_fitting"]'::jsonb,'diagnosis','dial_hands'),
  ('strip_down','keyless_side','choice','[{"value":"normal","label":"No obvious fault"},{"value":"wear_damage","label":"Wear or damage found"},{"value":"missing_part","label":"Part missing"},{"value":"unexpected_layout","label":"Unexpected layout / assembly"}]'::jsonb,'["wear_damage","missing_part","unexpected_layout"]'::jsonb,'diagnosis','keyless'),
  ('strip_down','train_side','choice','[{"value":"normal","label":"No obvious fault"},{"value":"wear_damage","label":"Wear or damage found"},{"value":"missing_part","label":"Part missing"},{"value":"unexpected_layout","label":"Unexpected layout / assembly"}]'::jsonb,'["wear_damage","missing_part","unexpected_layout"]'::jsonb,'diagnosis','train'),
  ('strip_down','escapement_balance','choice','[{"value":"normal","label":"No obvious fault"},{"value":"pivot_jewel","label":"Pivot / jewel concern"},{"value":"hairspring","label":"Hairspring concern"},{"value":"escapement","label":"Escapement concern"},{"value":"damage_other","label":"Other damage / abnormality"}]'::jsonb,'["pivot_jewel","hairspring","escapement","damage_other"]'::jsonb,'diagnosis','balance_escapement'),
  ('strip_down','strip_findings','choice','[{"value":"none","label":"No additional faults found"},{"value":"faults_recorded","label":"Faults recorded"},{"value":"needs_further_inspection","label":"Needs further inspection"}]'::jsonb,'["needs_further_inspection"]'::jsonb,'diagnosis','strip_down'),
  ('inspection','barrel_mainspring','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"wear","label":"Wear present"},{"value":"damaged","label":"Damaged / failed"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["wear","damaged","uncertain"]'::jsonb,'diagnosis','barrel'),
  ('inspection','train','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"pivot_jewel","label":"Pivot / jewel issue"},{"value":"tooth_pinion","label":"Wheel tooth / pinion issue"},{"value":"endshake","label":"Endshake / side shake issue"},{"value":"binding","label":"Binding / poor freedom"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["pivot_jewel","tooth_pinion","endshake","binding","uncertain"]'::jsonb,'diagnosis','train'),
  ('inspection','jewels','choice','[{"value":"serviceable","label":"Intact and serviceable"},{"value":"contaminated","label":"Contaminated"},{"value":"cracked_chipped","label":"Cracked / chipped"},{"value":"displaced","label":"Loose / displaced"},{"value":"worn","label":"Worn"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["contaminated","cracked_chipped","displaced","worn","uncertain"]'::jsonb,'diagnosis','jewels'),
  ('inspection','escapement','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"escape_wheel","label":"Escape-wheel issue"},{"value":"pallet_stone","label":"Pallet-stone issue"},{"value":"fork_guard","label":"Fork / guard issue"},{"value":"roller_safety","label":"Roller / safety-action issue"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["escape_wheel","pallet_stone","fork_guard","roller_safety","uncertain"]'::jsonb,'diagnosis','escapement'),
  ('inspection','balance','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"pivot_staff","label":"Pivot / staff issue"},{"value":"hairspring","label":"Hairspring issue"},{"value":"roller_impulse","label":"Roller / impulse-jewel issue"},{"value":"poise_endshake","label":"Poise / endshake concern"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["pivot_staff","hairspring","roller_impulse","poise_endshake","uncertain"]'::jsonb,'diagnosis','balance'),
  ('inspection','keyless','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"wear","label":"Wear / rough contact surfaces"},{"value":"lever_spring","label":"Lever / spring issue"},{"value":"pinion","label":"Winding / sliding-pinion issue"},{"value":"stem_crown","label":"Stem / crown issue"},{"value":"missing","label":"Part missing"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["wear","lever_spring","pinion","stem_crown","missing","uncertain"]'::jsonb,'diagnosis','keyless'),
  ('inspection','parts_decision','choice','[{"value":"none","label":"No replacement currently needed"},{"value":"replacement_needed","label":"Replacement part required"},{"value":"donor_candidate","label":"Donor part worth investigating"},{"value":"research_needed","label":"Compatibility / reference research needed"}]'::jsonb,'[]'::jsonb,'parts','compatibility'),
  ('cleaning','cleaning_exclusions','choice','[{"value":"none","label":"No exclusions identified"},{"value":"exclusions","label":"Cleaning exclusions identified"},{"value":"uncertain","label":"Unsure whether a component is safe to clean normally"}]'::jsonb,'["uncertain"]'::jsonb,'knowledge','cleaning'),
  ('cleaning','rinse_dry','choice','[{"value":"satisfactory","label":"Clean, rinsed and dry"},{"value":"contamination","label":"Contamination remains"},{"value":"moisture","label":"Moisture remains"},{"value":"residue","label":"Cleaning residue remains"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["contamination","moisture","residue","uncertain"]'::jsonb,'diagnosis','cleaning'),
  ('cleaning','post_clean_inspection','choice','[{"value":"serviceable","label":"No new fault visible"},{"value":"damage_visible","label":"Damage now visible"},{"value":"contamination_remains","label":"Contamination remains"},{"value":"uncertain","label":"Needs closer inspection"}]'::jsonb,'["damage_visible","contamination_remains","uncertain"]'::jsonb,'diagnosis','inspection'),
  ('barrel_mainspring','barrel_condition','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"wear","label":"Wear present"},{"value":"damaged","label":"Damaged / distorted"},{"value":"hook_fault","label":"Hook / engagement surface fault"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["wear","damaged","hook_fault","uncertain"]'::jsonb,'diagnosis','barrel'),
  ('barrel_mainspring','spring_condition','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"set_usable","label":"Set but potentially reusable"},{"value":"cracked_damaged","label":"Cracked / damaged"},{"value":"hook_bridle_fault","label":"Hook / bridle fault"},{"value":"incorrect","label":"Incorrect / unsuitable spring"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["set_usable","cracked_damaged","hook_bridle_fault","incorrect","uncertain"]'::jsonb,'parts','mainspring'),
  ('barrel_mainspring','lubrication_reference','choice','[{"value":"documented","label":"Movement-specific reference available"},{"value":"general_practice","label":"Using general bench practice"},{"value":"missing","label":"Reference still needed"}]'::jsonb,'[]'::jsonb,'knowledge','lubrication_barrel'),
  ('train_test','endshake','choice','[{"value":"acceptable","label":"Acceptable"},{"value":"excessive","label":"Excessive"},{"value":"insufficient","label":"Insufficient / pinched"},{"value":"uncertain","label":"Uncertain"}]'::jsonb,'["excessive","insufficient","uncertain"]'::jsonb,'measurement','train'),
  ('train_test','bridge_seating','choice','[{"value":"free","label":"Seats freely and correctly"},{"value":"pressure","label":"Only seats under pressure"},{"value":"pivot_not_engaging","label":"Pivot not engaging jewel"},{"value":"misalignment","label":"Bridge / plate misalignment suspected"},{"value":"uncertain","label":"Uncertain"}]'::jsonb,'["pressure","pivot_not_engaging","misalignment","uncertain"]'::jsonb,'diagnosis','train'),
  ('keyless_winding','lubrication_reference','choice','[{"value":"documented","label":"Movement-specific reference available"},{"value":"general_practice","label":"Using general bench practice"},{"value":"missing","label":"Reference still needed"}]'::jsonb,'[]'::jsonb,'knowledge','lubrication_keyless'),
  ('keyless_winding','winding_function','choice','[{"value":"smooth","label":"Smooth and positive"},{"value":"rough","label":"Rough / gritty"},{"value":"slips","label":"Slips / intermittent engagement"},{"value":"blocks","label":"Blocks"},{"value":"no_torque","label":"No useful torque transmitted"},{"value":"other","label":"Other abnormal behaviour"}]'::jsonb,'["rough","slips","blocks","no_torque","other"]'::jsonb,'diagnosis','keyless'),
  ('keyless_winding','setting_function','choice','[{"value":"smooth","label":"Smooth and positive"},{"value":"stiff","label":"Stiff"},{"value":"slips","label":"Slips / fails to engage"},{"value":"blocks","label":"Blocks"},{"value":"positions","label":"Crown positions incomplete / unclear"},{"value":"other","label":"Other abnormal behaviour"}]'::jsonb,'["stiff","slips","blocks","positions","other"]'::jsonb,'diagnosis','keyless'),
  ('escapement','inspect_escape','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"tooth_damage","label":"Tooth damage"},{"value":"pivot_jewel","label":"Pivot / jewel issue"},{"value":"freedom","label":"Freedom / endshake issue"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["tooth_damage","pivot_jewel","freedom","uncertain"]'::jsonb,'diagnosis','escapement'),
  ('escapement','inspect_pallet','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"stone","label":"Pallet-stone issue"},{"value":"fork_guard","label":"Fork / guard-pin issue"},{"value":"banking","label":"Banking relationship issue"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["stone","fork_guard","banking","uncertain"]'::jsonb,'diagnosis','escapement'),
  ('escapement','lock_drop','choice','[{"value":"acceptable","label":"Lock / drop appears acceptable"},{"value":"uneven","label":"Uneven"},{"value":"excessive","label":"Excessive lock / drop"},{"value":"insufficient","label":"Insufficient / unsafe lock"},{"value":"fails_lock","label":"Fails to lock correctly"},{"value":"banking","label":"Banking / fork action issue"},{"value":"uncertain","label":"Uncertain"}]'::jsonb,'["uneven","excessive","insufficient","fails_lock","banking","uncertain"]'::jsonb,'diagnosis','escapement'),
  ('escapement','lubrication_reference','choice','[{"value":"documented","label":"Movement-specific reference available"},{"value":"general_practice","label":"Using general bench practice"},{"value":"missing","label":"Reference still needed"}]'::jsonb,'[]'::jsonb,'knowledge','lubrication_escapement'),
  ('balance','pivot_jewel_check','choice','[{"value":"serviceable","label":"Pivots and jewels serviceable"},{"value":"pivot_damage","label":"Pivot / staff damage"},{"value":"jewel_damage","label":"Jewel damage / displacement"},{"value":"contamination","label":"Contamination remains"},{"value":"endshake","label":"Endshake / seating concern"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["pivot_damage","jewel_damage","contamination","endshake","uncertain"]'::jsonb,'diagnosis','balance'),
  ('balance','hairspring_check','choice','[{"value":"free_centered","label":"Free and centred"},{"value":"touching","label":"Touching / interference"},{"value":"deformed","label":"Deformed / uneven coils"},{"value":"stud_collet","label":"Stud / collet issue"},{"value":"clearance","label":"Coil / bridge clearance issue"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["touching","deformed","stud_collet","clearance","uncertain"]'::jsonb,'diagnosis','balance'),
  ('balance','roller_check','choice','[{"value":"serviceable","label":"Serviceable"},{"value":"impulse_jewel","label":"Impulse-jewel issue"},{"value":"roller_table","label":"Roller-table issue"},{"value":"safety_action","label":"Safety / guard action issue"},{"value":"uncertain","label":"Condition uncertain"}]'::jsonb,'["impulse_jewel","roller_table","safety_action","uncertain"]'::jsonb,'diagnosis','balance'),
  ('balance','stable_run','choice','[{"value":"sustained","label":"Starts and sustains running"},{"value":"intermittent","label":"Runs intermittently"},{"value":"wont_start","label":"Will not start normally"},{"value":"position_stop","label":"Stops in a position"},{"value":"uncertain","label":"Behaviour uncertain"}]'::jsonb,'["intermittent","wont_start","position_stop","uncertain"]'::jsonb,'diagnosis','balance'),
  ('lubrication_final_assembly','lubrication_plan','choice','[{"value":"documented","label":"Movement-specific reference available"},{"value":"general_practice","label":"Using general bench practice"},{"value":"missing","label":"Reference still needed"}]'::jsonb,'[]'::jsonb,'knowledge','lubrication'),
  ('lubrication_final_assembly','lubrication_visual','choice','[{"value":"correct","label":"Looks correct"},{"value":"over_oiled","label":"Over-oiled"},{"value":"dry_point","label":"Required point appears dry"},{"value":"contamination","label":"Contamination present"},{"value":"migration","label":"Lubricant migration"},{"value":"uncertain","label":"Uncertain"}]'::jsonb,'["over_oiled","dry_point","contamination","migration","uncertain"]'::jsonb,'diagnosis','lubrication'),
  ('regulation','timing_reference','choice','[{"value":"documented","label":"Documented reference confirmed"},{"value":"manual_verified","label":"Manually verified"},{"value":"unknown","label":"Reference uncertain / missing"}]'::jsonb,'[]'::jsonb,'knowledge','timing_specs'),
  ('regulation','post_assembly_run','tool_result','[]'::jsonb,'[]'::jsonb,'timing','regulation'),
  ('regulation','position_checks','tool_result','[]'::jsonb,'[]'::jsonb,'timing','regulation'),
  ('regulation','regulation_review','choice','[{"value":"acceptable","label":"Improved and acceptable"},{"value":"improved_not_acceptable","label":"Improved but not yet acceptable"},{"value":"unchanged","label":"Little / no improvement"},{"value":"worse","label":"Worse"},{"value":"unstable","label":"Unstable / inconsistent"}]'::jsonb,'["improved_not_acceptable","unchanged","worse","unstable"]'::jsonb,'diagnosis','timing'),
  ('casing','hand_clearance','choice','[{"value":"clear","label":"Clear through full cycle"},{"value":"hand_hand","label":"Hand-to-hand contact"},{"value":"dial","label":"Hand-to-dial / marker contact"},{"value":"crystal","label":"Hand-to-crystal contact"},{"value":"uncertain","label":"Clearance uncertain"}]'::jsonb,'["hand_hand","dial","crystal","uncertain"]'::jsonb,'diagnosis','casing'),
  ('casing','stem_crown','choice','[{"value":"smooth","label":"Smooth and correct after casing"},{"value":"rough","label":"Rough / gritty"},{"value":"stiff","label":"Stiff"},{"value":"slips","label":"Slips / disengages"},{"value":"blocks","label":"Blocks"},{"value":"uncertain","label":"Uncertain"}]'::jsonb,'["rough","stiff","slips","blocks","uncertain"]'::jsonb,'diagnosis','casing'),
  ('casing','movement_security','choice','[{"value":"secure","label":"Secure without distortion"},{"value":"shifts","label":"Movement shifts in case"},{"value":"retention","label":"Clamp / ring / spacer issue"},{"value":"distortion","label":"Retention may distort movement"},{"value":"uncertain","label":"Security uncertain"}]'::jsonb,'["shifts","retention","distortion","uncertain"]'::jsonb,'diagnosis','casing'),
  ('final_qc','final_functions','choice','[{"value":"pass","label":"All functions pass"},{"value":"winding","label":"Winding issue"},{"value":"setting","label":"Setting issue"},{"value":"running","label":"Running / stopping issue"},{"value":"multiple","label":"Multiple functional issues"}]'::jsonb,'["winding","setting","running","multiple"]'::jsonb,'diagnosis','final_qc'),
  ('final_qc','final_timing','tool_result','[]'::jsonb,'[]'::jsonb,'timing','final_qc'),
  ('final_qc','final_visual','choice','[{"value":"pass","label":"Visual / assembly QC pass"},{"value":"cosmetic","label":"Cosmetic issue remains"},{"value":"assembly","label":"Assembly / fit issue"},{"value":"evidence_missing","label":"Required visual evidence missing"}]'::jsonb,'["cosmetic","assembly","evidence_missing"]'::jsonb,'diagnosis','final_qc'),
  ('final_qc','qc_evidence','choice','[{"value":"complete","label":"Required evidence complete"},{"value":"photo_missing","label":"Photo evidence missing"},{"value":"measurement_missing","label":"Measurement missing"},{"value":"timing_missing","label":"Timing evidence missing"},{"value":"other_missing","label":"Other evidence missing"}]'::jsonb,'["photo_missing","measurement_missing","timing_missing","other_missing"]'::jsonb,'diagnosis','final_qc')
)
update public.work_template_step_checks c
set answer_kind = cfg.answer_kind, answer_options = cfg.answer_options, problem_values = cfg.problem_values, tool_key = cfg.tool_key, knowledge_scope = cfg.knowledge_scope
from public.work_template_steps s, config cfg
where c.template_step_id = s.id and s.step_key = cfg.step_key and c.check_key = cfg.check_key;

update public.work_template_step_checks c
set check_type = 'timing', evidence_required = true
from public.work_template_steps s
where c.template_step_id = s.id and ((s.step_key = 'pre_service_timing' and c.check_key = 'baseline_run') or (s.step_key = 'demagnetise_check' and c.check_key = 'timing_effect') or (s.step_key = 'regulation' and c.check_key in ('post_assembly_run','position_checks')) or (s.step_key = 'final_qc' and c.check_key = 'final_timing'));

insert into public.work_template_step_checks (workspace_id, template_step_id, check_key, label, description, sequence, required, check_type, tool_key, knowledge_scope, evidence_required, answer_kind, answer_options, activation_rule, problem_values)
select s.workspace_id, s.id, v.check_key, v.label, v.description, v.sequence, v.required, v.check_type, v.tool_key, v.knowledge_scope, v.evidence_required, v.answer_kind, v.answer_options, v.activation_rule, v.problem_values
from public.work_template_steps s join (values
('movement_removal','stem_removal_detail','Narrow the stem / crown resistance','Record where the resistance appears to come from before forcing anything. If the release method is uncertain, use movement-specific Knowledge or Research.',25,true,'decision','diagnosis','keyless',false,'choice','[{"value":"release_method","label":"Release method / release point"},{"value":"crown_tube","label":"Crown / case-tube drag"},{"value":"stem_alignment","label":"Stem alignment / bending"},{"value":"internal_keyless","label":"Internal keyless resistance"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'{"parent_key":"stem_crown_removal","values":["resistance","unable","uncertain"]}'::jsonb,'["uncertain"]'::jsonb),
('movement_removal','retention_fault_detail','Narrow the casing / retention issue','Identify whether the problem is a clamp or screw, movement ring/spacer, case geometry, or something still uncertain.',35,true,'decision','diagnosis','casing',false,'choice','[{"value":"clamp_screw","label":"Clamp / screw"},{"value":"ring_spacer","label":"Movement ring / spacer"},{"value":"case_geometry","label":"Case geometry / fit"},{"value":"missing_part","label":"Missing retention part"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'{"parent_key":"case_retention","values":["damaged_missing","distorting"]}'::jsonb,'["missing_part","uncertain"]'::jsonb),
('movement_removal','identity_followup','Record the new movement / case evidence','Record the newly visible mark, number or construction clue. Use Research if it changes or fails to confirm the current identity.',45,false,'observation','research','identification',true,'text','[]'::jsonb,'{"parent_key":"case_movement_marks","values":["new_marks","still_uncertain"]}'::jsonb,'[]'::jsonb),
('strip_down','dial_hands_detail','Narrow the dial / hands issue','Identify whether the concern is hand fit, dial feet/fixings, friction/damage, or an unusual construction that needs reference evidence.',25,true,'decision','diagnosis','dial_hands',false,'choice','[{"value":"hand_fit","label":"Hand fit / removal resistance"},{"value":"dial_fixing","label":"Dial feet / fixing"},{"value":"damage","label":"Existing or removal damage"},{"value":"unusual","label":"Unusual construction"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'{"parent_key":"dial_hands","values":["tight","damage_found","unusual_fitting"]}'::jsonb,'["uncertain"]'::jsonb),
('strip_down','keyless_strip_detail','Narrow the keyless strip-down finding','Identify the area affected so later inspection and parts work can be targeted.',35,true,'decision','diagnosis','keyless',false,'choice','[{"value":"stem_crown","label":"Stem / crown"},{"value":"lever_spring","label":"Lever / spring"},{"value":"pinions","label":"Winding / sliding pinions"},{"value":"missing","label":"Missing component"},{"value":"unknown","label":"Other / uncertain"}]'::jsonb,'{"parent_key":"keyless_side","values":["wear_damage","missing_part","unexpected_layout"]}'::jsonb,'["missing","unknown"]'::jsonb),
('strip_down','train_strip_detail','Narrow the train strip-down finding','Identify the visible area of concern before cleaning removes useful evidence.',45,true,'decision','diagnosis','train',false,'choice','[{"value":"wheel_teeth","label":"Wheel teeth / pinion"},{"value":"pivot_jewel","label":"Pivot / jewel"},{"value":"bridge_seating","label":"Bridge / seating"},{"value":"missing","label":"Missing component"},{"value":"unknown","label":"Other / uncertain"}]'::jsonb,'{"parent_key":"train_side","values":["wear_damage","missing_part","unexpected_layout"]}'::jsonb,'["missing","unknown"]'::jsonb),
('strip_down','balance_escape_strip_detail','Narrow the balance / escapement finding','Record the most relevant area so Calibre can carry it into component inspection and diagnosis.',55,true,'decision','diagnosis','balance_escapement',false,'choice','[{"value":"pivot_jewel","label":"Balance pivot / jewel"},{"value":"hairspring","label":"Hairspring"},{"value":"roller_impulse","label":"Roller / impulse"},{"value":"pallet_escape","label":"Pallet / escape wheel"},{"value":"unknown","label":"Other / uncertain"}]'::jsonb,'{"parent_key":"escapement_balance","values":["pivot_jewel","hairspring","escapement","damage_other"]}'::jsonb,'["unknown"]'::jsonb),
('strip_down','strip_fault_summary','Summarise the unresolved strip-down finding','Record the fault or uncertainty that still needs to be resolved before the job plan can be treated as complete.',65,true,'observation','diagnosis','strip_down',true,'text','[]'::jsonb,'{"parent_key":"strip_findings","values":["faults_recorded","needs_further_inspection"]}'::jsonb,'[]'::jsonb),
('inspection','barrel_inspection_detail','Narrow the barrel / mainspring finding','Identify the affected area before deciding whether it is serviceable, repairable or needs a part.',15,true,'decision','diagnosis','barrel',false,'choice','[{"value":"barrel_wall_lid","label":"Barrel wall / lid"},{"value":"arbor_bearing","label":"Arbor / bearing surface"},{"value":"hook","label":"Hook / engagement"},{"value":"mainspring","label":"Mainspring"},{"value":"bridle","label":"Bridle / slipping attachment"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'{"parent_key":"barrel_mainspring","values":["wear","damaged","uncertain"]}'::jsonb,'["uncertain"]'::jsonb),
('inspection','train_inspection_detail','Record the train fault location','Identify the wheel, pivot, jewel or bridge involved where possible. A note can capture the exact wheel or location.',25,true,'observation','diagnosis','train',true,'text','[]'::jsonb,'{"parent_key":"train","values":["pivot_jewel","tooth_pinion","endshake","binding","uncertain"]}'::jsonb,'[]'::jsonb),
('inspection','jewel_inspection_detail','Record the affected jewel','Record which jewel is affected and what you can actually see. Avoid assuming the cause from appearance alone.',35,true,'observation','diagnosis','jewels',true,'text','[]'::jsonb,'{"parent_key":"jewels","values":["contaminated","cracked_chipped","displaced","worn","uncertain"]}'::jsonb,'[]'::jsonb),
('inspection','escapement_inspection_detail','Record the escapement fault location','Record the component and observation that make the escapement abnormal or uncertain.',45,true,'observation','diagnosis','escapement',true,'text','[]'::jsonb,'{"parent_key":"escapement","values":["escape_wheel","pallet_stone","fork_guard","roller_safety","uncertain"]}'::jsonb,'[]'::jsonb),
('inspection','balance_inspection_detail','Record the balance fault evidence','Record the exact pivot, jewel, hairspring, roller or endshake observation. This should be evidence, not just a diagnosis label.',55,true,'observation','diagnosis','balance',true,'text','[]'::jsonb,'{"parent_key":"balance","values":["pivot_staff","hairspring","roller_impulse","poise_endshake","uncertain"]}'::jsonb,'[]'::jsonb),
('inspection','keyless_inspection_detail','Record the keyless fault evidence','Record the exact worn, broken, missing or abnormal component and how it affects operation.',65,true,'observation','diagnosis','keyless',true,'text','[]'::jsonb,'{"parent_key":"keyless","values":["wear","lever_spring","pinion","stem_crown","missing","uncertain"]}'::jsonb,'[]'::jsonb),
