('cleaning','post_clean_fault_area','Locate what the post-clean inspection revealed','Cleaning often exposes wear that was hidden by contamination. Identify the area that now needs attention.',55,true,'decision','diagnosis','inspection',false,'choice','[{"value":"pivot_jewel","label":"Pivot / jewel"},{"value":"wheel_teeth","label":"Wheel / pinion"},{"value":"escapement","label":"Escapement"},{"value":"balance","label":"Balance / hairspring"},{"value":"keyless","label":"Keyless / winding"},{"value":"barrel","label":"Barrel / mainspring"},{"value":"reclean","label":"Needs re-cleaning"},{"value":"uncertain","label":"Still uncertain"}]'::jsonb,'{"parent_key":"post_clean_inspection","values":["damage_visible","contamination_remains","uncertain"]}'::jsonb,'["uncertain"]'::jsonb),
