) as v(step_key,check_key,label,description,sequence,required,check_type,tool_key,knowledge_scope,evidence_required,answer_kind,answer_options,activation_rule,problem_values) on s.step_key = v.step_key
where not exists (select 1 from public.work_template_step_checks existing where existing.template_step_id = s.id and existing.check_key = v.check_key);

update public.work_step_checks w
set answer_kind = t.answer_kind, answer_options = t.answer_options, activation_rule = t.activation_rule, problem_values = t.problem_values, tool_key = t.tool_key, knowledge_scope = t.knowledge_scope, check_type = t.check_type, evidence_required = t.evidence_required, is_active = (t.activation_rule = '{}'::jsonb), state_reason = case when t.activation_rule = '{}'::jsonb then '' else 'Waiting for parent result' end
from public.work_template_step_checks t join public.work_checklist_steps s on s.template_step_id = t.template_step_id join public.work_records wr on wr.id = s.work_id and wr.workspace_id = s.workspace_id
where w.template_step_check_id = t.id and w.checklist_step_id = s.id and wr.status not in ('complete','cancelled') and w.status in ('not_started','in_progress') and coalesce(w.origin_kind,'template') = 'template';

insert into public.work_step_checks (workspace_id, work_id, item_id, checklist_step_id, template_step_check_id, check_key, label, description, sequence, required, check_type, tool_key, knowledge_scope, evidence_required, answer_kind, answer_options, activation_rule, problem_values, is_active, state_reason, created_by, origin_kind)
select s.workspace_id, s.work_id, s.item_id, s.id, t.id, t.check_key, t.label, t.description, t.sequence, t.required, t.check_type, t.tool_key, t.knowledge_scope, t.evidence_required, t.answer_kind, t.answer_options, t.activation_rule, t.problem_values, (t.activation_rule = '{}'::jsonb), case when t.activation_rule = '{}'::jsonb then '' else 'Waiting for parent result' end, s.created_by, 'template'
from public.work_checklist_steps s join public.work_records wr on wr.id = s.work_id and wr.workspace_id = s.workspace_id join public.work_template_step_checks t on t.template_step_id = s.template_step_id
where wr.status not in ('complete','cancelled') and not exists (select 1 from public.work_step_checks existing where existing.checklist_step_id = s.id and existing.check_key = t.check_key)
on conflict (checklist_step_id, check_key) do nothing;

update public.work_step_checks child set parent_check_id = parent.id
from public.work_step_checks parent join public.work_records wr on wr.id = parent.work_id and wr.workspace_id = parent.workspace_id
where wr.status not in ('complete','cancelled') and child.workspace_id = parent.workspace_id and child.work_id = parent.work_id and child.checklist_step_id = parent.checklist_step_id and child.activation_rule <> '{}'::jsonb and child.activation_rule->>'parent_key' = parent.check_key;

update public.work_step_checks w set is_active = (w.activation_rule = '{}'::jsonb), state_reason = case when w.activation_rule = '{}'::jsonb then '' else 'Waiting for parent result' end
from public.work_records wr where wr.id = w.work_id and wr.workspace_id = w.workspace_id and wr.status not in ('complete','cancelled') and w.status in ('not_started','in_progress');

do $$ declare i integer; begin
  for i in 1..4 loop
    update public.work_step_checks child
    set is_active = parent.is_active and exists (select 1 from jsonb_array_elements_text(coalesce(child.activation_rule->'values','[]'::jsonb)) allowed(value) where allowed.value = parent.answer_value),
        state_reason = case when parent.is_active and exists (select 1 from jsonb_array_elements_text(coalesce(child.activation_rule->'values','[]'::jsonb)) allowed(value) where allowed.value = parent.answer_value) then '' when not parent.is_active then concat('Parent branch inactive: ', parent.label) when btrim(parent.answer_value) = '' then concat('Waiting for: ', parent.label) else concat('Ruled out by ', parent.label, ' = ', parent.answer_value) end
    from public.work_step_checks parent join public.work_records wr on wr.id = parent.work_id and wr.workspace_id = parent.workspace_id
    where wr.status not in ('complete','cancelled') and child.workspace_id = parent.workspace_id and child.work_id = parent.work_id and child.checklist_step_id = parent.checklist_step_id and child.parent_check_id = parent.id and child.status in ('not_started','in_progress');
  end loop;
end $$;